    // numeric prefixes/signs. Grammar hardening is a separate semantic change.
    const std::locale locale;
    const auto &chars = std::use_facet<std::ctype<char>>(locale);
    const char *at = s.data() + n + 2;
    const char *end = s.data() + s.size();
    std::string utime, stime, start;
    char state = 0;
    for (unsigned field = 0; field < 20; field++) {
        at = chars.scan_not(std::ctype_base::space, at, end);
        if (at == end)
            return {};
        const char *next = chars.scan_is(std::ctype_base::space, at, end);
        if (field == 0)
            state = *at;
        else if (field == 11)
            utime.assign(at, next);
        else if (field == 12)
            stime.assign(at, next);
        else if (field == 19)
            start.assign(at, next);
        at = next;
    }
    try {
        out.start = std::stoull(start);
        out.ticks = std::stoull(utime) + std::stoull(stime);
        out.state = state;
    } catch (...) {
        return {};
    }
    if (out.state == 'Z' || out.state == 'X')
        out.start = 0;
