    char kind = 0;
    std::bitset<128> chars;
};
inline std::vector<GlobToken> compileGlob(const std::string &pattern) {
    require(!pattern.empty() && pattern.size() <= 64, "glob size");
    std::vector<GlobToken> tokens;
    for (size_t i = 0; i < pattern.size(); i++) {
        unsigned char c = pattern[i];
        require(c >= 32 && c < 127 && c != '\\', "glob character");
        GlobToken t;
        if (c == '*' || c == '?')
            t.kind = c;
        else if (c == '[') {
            t.kind = 'c';
            bool any = false;
            while (++i < pattern.size() && pattern[i] != ']') {
                unsigned char a = pattern[i], b = a;
                require(a >= 32 && a < 127 && a != '[' && a != '\\' && a != '!' && a != '^', "glob class");
                if (i + 1 < pattern.size() && pattern[i + 1] == '-') {
                    require(i + 2 < pattern.size() && pattern[i + 2] != ']', "glob range");
                    b = pattern[i + 2];
                    i += 2;
                    require(b >= a && b < 127 && b != '[' && b != '\\', "glob range order");
                }
                for (unsigned n = a; n <= b; n++)
                    t.chars.set(n);
                any = true;
            }
            require(i < pattern.size() && any, "unclosed/empty glob class");
        } else {
            require(c != ']', "unpaired glob close");
            t.kind = 'c';
            t.chars.set(c);
        }
        tokens.push_back(t);
    }
    return tokens;
}
inline bool globMatch(const std::vector<GlobToken> &tokens, const std::string &value) {
    if (value.size() > 64)
        return false;
    // Bounded DP, O(64*64), no backtracking or regular-expression engine.
    std::array<bool, 65> prev{};
    prev[0] = true;
    for (auto &t : tokens) {
        std::array<bool, 65> next{};
        next[0] = t.kind == '*' && prev[0];
        for (size_t j = 1; j <= value.size(); j++) {
            unsigned char c = value[j - 1];
            next[j] =
                t.kind == '*' ? (prev[j] || next[j - 1]) : prev[j - 1] && (t.kind == '?' || (c < 128 && t.chars[c]));
        }
        prev = next;
    }
    return prev[value.size()];
}
