inline bool packageLabel(const std::string &s) {
    if (s.empty() || s.size() > 255 || s.find('.') == s.npos)
        return false;
    bool first = true;
    for (char c : s) {
        if (c == '.') {
            if (first)
                return false;
            first = true;
            continue;
        }
        if (first && !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z'))
            return false;
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'))
            return false;
        first = false;
    }
    return !first;
}
