inline Config parseConfig(const std::string &text, Mask available, bool legacyMigration = false) {
    require(!text.empty() && text.size() <= 65536 && text.find('\0') == text.npos, "config size/NUL");
    Config c;
    bool seenEnabled = false, seenSchema = false, seenDebug = false, seenRuntimeDefaults = false;
    std::set<std::string> runtimeProfiles;
    std::istringstream all(text);
    std::string line;
    while (std::getline(all, line)) {
        line = trim(line);
        if (line.empty() || line[0] == '#')
            continue;
        require(line.size() < 1024, "line length");
        std::istringstream in(line);
        std::string kind, extra;
        in >> kind;
        if (kind == "schema") {
            std::string v;
            in >> v;
            require(!seenSchema && (v == "3" || (legacyMigration && v == "2")), "schema 3 required", ErrorCode::CONFIG);
            c.schema = number(v);
            seenSchema = true;
        } else if (kind == "enabled") {
            std::string v;
            in >> v;
            require(!seenEnabled && (v == "true" || v == "false"), "enabled value");
            seenEnabled = true;
            c.enabled = v == "true";
        } else if (kind == "debug") {
            std::string v;
            in >> v;
            require(!seenDebug && (v == "true" || v == "false"), "debug value");
            seenDebug = true;
            c.debug = v == "true";
        } else if (kind == "runtime_defaults") {
            std::string mode, rt;
            in >> mode >> rt;
            require(!seenRuntimeDefaults, "duplicate runtime defaults");
            seenRuntimeDefaults = true;
            c.mode = number(mode);
            c.rt = number(rt);
            require(c.mode >= 0 && c.mode <= 2 && c.rt >= 0 && c.rt <= 1, "runtime defaults range");
        } else if (kind == "runtime") {
            std::string name, mode, rt, placement, marker;
            in >> name >> mode >> rt >> placement >> marker;
            require(c.profiles.count(name) && runtimeProfiles.insert(name).second, "runtime profile/duplicate");
            auto &r = c.profiles.at(name).runtime;
            r.mode = number(mode);
            r.rt = number(rt);
            r.preset = placement == "preset";
            r.marker = marker;
            require(r.mode >= -1 && r.mode <= 2 && r.rt >= -1 && r.rt <= 1 && (placement == "explicit" || r.preset) &&
                        (marker == "none" || marker == "dummy" || marker == "double"),
                    "runtime profile values");
            require(r.preset || marker == "none", "marker requires mode preset");
        } else if (kind == "profile") {
            std::string name, cpu;
            in >> name >> cpu;
            require(label(name) && !c.profiles.count(name), "duplicate/invalid profile");
            c.profiles[name].general = cpus(cpu);
        } else if (kind == "thread") {
            std::string name, cpu, priority, selector;
            Rule r;
            in >> name >> r.cls >> r.kind >> std::quoted(r.pattern) >> selector >> priority >> cpu;
            require(c.profiles.count(name) && label(r.cls) && (matchKind(r.kind) || r.kind == "glob") &&
                        (!r.pattern.empty() || r.kind == "contains") && r.pattern.size() <= 64,
                    "thread rule");
            require(r.pattern.find_first_of("\r\n\t") == r.pattern.npos, "thread control character");
            if (selector != "selector=all") {
                require(selector.rfind("selector=rank:", 0) == 0, "explicit selector required");
                int rank = number(selector.substr(14));
                require(rank >= 1 && rank <= 1024, "rank bound");
                r.rank = static_cast<unsigned>(rank);
            }
            if (r.kind == "glob")
                r.glob = compileGlob(r.pattern);
            r.priority = number(priority);
            r.mask = cpus(cpu);
            auto &rules = c.profiles[name].rules;
            for (auto &old : rules)
                require(old.priority != r.priority && (old.cls != r.cls || (old.mask == r.mask && old.rank == r.rank)),
                        "ambiguous thread rules/group selector");
            rules.push_back(r);
        } else if (kind == "package") {
            Mapping r;
            std::string priority;
            in >> r.kind >> r.package >> r.profile >> priority;
            require(matchKind(r.kind) && label(r.package) && (r.kind != "exact" || packageLabel(r.package)) &&
                        c.profiles.count(r.profile),
                    "package mapping");
            r.priority = number(priority);
            for (auto &old : c.packages)
                require(old.priority != r.priority && (old.kind != r.kind || old.package != r.package),
                        "package priority tie/duplicate");
            c.packages.push_back(r);
        } else
            throw std::runtime_error("unknown config directive: " + kind);
        require(!(in >> extra), "extra config fields");
        require(c.packages.size() <= 512 && c.profiles.size() <= 64, "config bound");
    }
    require(seenSchema && seenEnabled, "missing schema/enabled header");
    require(c.schema == 3 || (!seenRuntimeDefaults && runtimeProfiles.empty()), "runtime requires schema 3");
    for (auto &[_, p] : c.profiles) {
        require((p.general & available) == p.general, "unavailable default CPU");
        require(p.rules.size() <= 32, "rule count");
        for (auto &r : p.rules)
            require((r.mask & available) == r.mask, "unavailable override CPU");
        std::sort(p.rules.begin(), p.rules.end(), [](auto &a, auto &b) { return a.priority > b.priority; });
    }
    std::sort(c.packages.begin(), c.packages.end(), [](auto &a, auto &b) { return a.priority > b.priority; });
    return c;
}
