    case Ownership::ZUIOPT_OWNED:
        return to == Ownership::REVOKE_PENDING || to == Ownership::RELEASING;
    case Ownership::REVOKE_PENDING:
        return to == Ownership::RELEASING;
    case Ownership::RELEASING:
