void activateAuthority(ProcessState &p, bool wanted, bool newScene, int64_t time, Runtime &runtime) {
    if (p.revoked())
        return; // Only explicit scene arbitration may leave pending.
    bool fresh = wanted && !p.releaseAuthorityForeground;
