        // Give that epoch its one window too; a delayed scene cannot extend it.
        if (fresh || (p.releaseParked && newScene)) {
            p.releaseParked = false;
            p.releaseBlocked = false;
            p.releaseRearmed = true;
            p.releaseStarted = time;
            p.releaseStep = 0;
