                while(!stop&&now()<end)std::this_thread::sleep_for(std::chrono::milliseconds(2));});
            struct Finish{std::atomic<bool>& stop;std::thread& worker;~Finish(){stop=true;if(worker.joinable())worker.join();}} finish{stop,worker};
