            <<",\"reduce_restore_type\":"<<std::quoted(reduce==-1?"SEMANTIC_RESTORE":"EXACT_RESTORE")<<",\"negative_reduce_normalization_qualified\":"<<(waltSemanticCapable?"true":"false")<<"}\n";
