        require(errno == ENOENT, "private stat");
        return false;
    }
    std::string get(const std::string &entry, size_t limit, bool optional = false) const {
        name(entry);
        int input = openat(fd, entry.c_str(), O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
        if (input < 0) {
            require(optional && errno == ENOENT, "private file open");
            return {};
        }
        try {
            file(input);
            struct stat st {};
            require(fstat(input, &st) == 0 && st.st_size >= 0 && static_cast<uint64_t>(st.st_size) <= limit,
                    "private file size");
            std::string out;
            char buffer[4096];
            for (;;) {
                auto n = ::read(input, buffer, sizeof(buffer));
                if (n < 0 && errno == EINTR)
                    continue;
                require(n >= 0, "private file read");
                if (!n)
                    break;
                out.append(buffer, n);
                require(out.size() <= limit, "private read bound");
            }
            close(input);
            return out;
        } catch (...) {
            close(input);
            throw;
        }
    }
    void sync() const {
        require(fsync(fd) == 0, "private directory sync");
    }
    void put(const std::string &entry, const std::string &data, bool exclusive = false) const {
        name(entry);
        if (exclusive)
            require(!exists(entry), "immutable generation exists");
        if (exists(entry)) {
            int old = openat(fd, entry.c_str(), O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
            try {
                file(old);
            } catch (...) {
                if (old >= 0)
                    close(old);
                throw;
            }
            close(old);
        }
        const auto temp = "tmp-" + randomId();
        int out = openat(fd, temp.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC | O_NOFOLLOW, 0600);
        require(out >= 0, "private staging create");
        try {
            putAll(out, data);
            require(fsync(out) == 0, "private file sync");
            close(out);
            out = -1;
            require(renameat(fd, temp.c_str(), fd, entry.c_str()) == 0, "private atomic rename");
            sync();
        } catch (...) {
            if (out >= 0)
                close(out);
            unlinkat(fd, temp.c_str(), 0);
            throw;
        }
    }
    void remove(const std::string &entry) const {
        name(entry);
        if (!exists(entry))
            return;
        int input = openat(fd, entry.c_str(), O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
        try {
            file(input);
        } catch (...) {
            if (input >= 0)
                close(input);
            throw;
        }
        close(input);
        require(unlinkat(fd, entry.c_str(), 0) == 0, "private unlink");
        sync();
    }
    std::vector<std::string> names(size_t limit = 64) const {
        int copy = openat(fd, ".", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        require(copy >= 0, "directory duplicate");
        DIR *dir = fdopendir(copy);
        if (!dir) {
            close(copy);
            throw std::runtime_error("directory enumeration");
        }
        std::vector<std::string> result;
        int error = 0;
        for (;;) {
            errno = 0;
            auto *entry = readdir(dir);
            if (!entry) {
                error = errno;
                break;
            }
            std::string n = entry->d_name;
            if (n != "." && n != "..")
                result.push_back(n);
            if (result.size() > limit) {
                closedir(dir);
                throw std::runtime_error("directory entry bound");
            }
        }
        closedir(dir);
        require(error == 0, "directory enumeration read");
        return result;
    }
};
