inline std::string base64(const std::string &s) {
    const std::string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    std::string out;
    for (size_t i = 0; i < s.size(); i += 3) {
        uint32_t n = uint32_t(static_cast<unsigned char>(s[i])) << 16;
        if (i + 1 < s.size())
            n |= uint32_t(static_cast<unsigned char>(s[i + 1])) << 8;
        if (i + 2 < s.size())
            n |= static_cast<unsigned char>(s[i + 2]);
        out += alphabet[n >> 18];
        out += alphabet[(n >> 12) & 63];
        out += i + 1 < s.size() ? alphabet[(n >> 6) & 63] : '=';
        out += i + 2 < s.size() ? alphabet[n & 63] : '=';
    }
    return out;
}
inline std::string unbase64(const std::string &s, size_t limit = 8192) {
    require(!s.empty() && s.size() <= (limit + 2) / 3 * 4 && s.size() % 4 == 0, "chunk base64 size");
    const std::string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    std::string out;
    for (size_t i = 0; i < s.size(); i += 4) {
        uint32_t n = 0;
        int count = 3;
        for (int j = 0; j < 4; j++) {
            auto at = alphabet.find(s[i + j]);
            if (s[i + j] == '=') {
                require(i + 4 == s.size() && j >= 2, "base64 padding");
                if (j == 2)
                    require(s[i + 3] == '=', "base64 padding order");
                at = 0;
                count--;
            } else
                require(at != alphabet.npos, "base64 alphabet");
            n = (n << 6) | at;
        }
        out += static_cast<char>(n >> 16);
        if (count >= 2)
            out += static_cast<char>(n >> 8);
        if (count == 3)
            out += static_cast<char>(n);
    }
    require(out.size() <= limit && base64(out) == s, "noncanonical base64");
    return out;
}
inline std::vector<std::string> fields(const std::string &text, char delimiter) {
    std::vector<std::string> out;
    size_t start = 0;
    for (;;) {
        auto end = text.find(delimiter, start);
        out.push_back(text.substr(start, end - start));
        if (end == text.npos)
            break;
        start = end + 1;
    }
    return out;
}

// Crash accounting never waits for rule commit/owner ACK. Its own tiny critical
// section has a 200 ms lock deadline; accounting failure durably fails closed.
class CrashLock {
    int fd = -1;

  public:
    explicit CrashLock(const PrivateDir &root) {
        fd = openat(root.fd, "crash.lock", O_RDWR | O_CREAT | O_CLOEXEC | O_NOFOLLOW, 0600);
        try {
            PrivateDir::file(fd);
            const auto deadline = now() + 200;
            while (flock(fd, LOCK_EX | LOCK_NB) != 0) {
                require((errno == EWOULDBLOCK || errno == EAGAIN || errno == EINTR) && now() < deadline,
                        "crash accounting lock deadline");
                usleep(1000);
            }
        } catch (...) {
            if (fd >= 0)
                close(fd);
            fd = -1;
            throw;
        }
    }
    ~CrashLock() {
        if (fd >= 0)
            close(fd);
    }
    CrashLock(const CrashLock &) = delete;
    CrashLock &operator=(const CrashLock &) = delete;
};
inline void crashFailure(const PrivateDir &root, const std::string &reason = "") {
    root.put("failure.v1", "ZUIOPT_FAILURE_V1\n" + trim(read("/proc/sys/kernel/random/boot_id")) + "\n" + reason);
}
inline bool accountCrash(const PrivateDir &root) {
    try {
        CrashLock lock(root);
        if (root.exists("failure.v1"))
            return true;
        auto boot = trim(read("/proc/sys/kernel/random/boot_id"));
        auto lines = fields(root.get("crashes.v1", 256, true), '\n');
        std::vector<int64_t> times;
        if (!lines.empty() && lines[0] == boot)
            for (size_t i = 1; i < lines.size(); i++)
                if (!lines[i].empty()) {
                    require(rx(lines[i], "[0-9]{1,16}") && times.size() < 3, "crash history");
                    auto t = std::stoll(lines[i]);
                    if (t <= now() && now() - t <= 60000)
                        times.push_back(t);
                }
        times.push_back(now());
        if (times.size() >= 3) {
            crashFailure(root);
            return true;
        }
        std::string data = boot + "\n";
        for (auto t : times)
            data += std::to_string(t) + "\n";
        root.put("crashes.v1", data);
        return false;
    } catch (...) {
        // Persist the uncountable crash instead of silently dropping it or
        // allowing another restart. Explicit next-boot reset remains required.
        crashFailure(root, "ACCOUNTING_UNAVAILABLE_CRASH_RETAINED\n");
        return true;
    }
}
inline bool crashGate(const std::string &path) {
    PrivateDir root(path);
    return accountCrash(root);
}

class RuleStore {
    PrivateDir root, generations;
    int lockFd = -1;
    std::string factory, factorySha;
    bool readOnly;
    RuleState load(const std::string &effective, bool legacyMigration = false) {
        auto parse = legacyMigration ? migrationRules : rules;
        auto canonical = [&](const std::string &text) {
            auto config = parse(text);
            return legacyMigration ? legacyCanonical(config) : dumpRules(config);
        };
        RuleState state;
        if (effective.empty())
            return state;
        parse(effective);
        auto id = generationOf(effective);
        PrivateDir d(generations, id);
        require(d.get("effective.conf", RULE_LIMIT) == effective, "generation commit content");
        state.effective = effective;
        if (d.exists("canonical_state.v2") || d.exists("canonical_state.v3")) {
            state.library = d.exists("canonical_state.v3");
            auto meta = fields(d.get(state.library ? "canonical_state.v3" : "canonical_state.v2", 2048), '\n');
            require(meta.size() == (state.library ? 11u : 9u) &&
                        meta[0] == (state.library ? "ZUIOPT_CANONICAL_STATE_V3" : "ZUIOPT_CANONICAL_STATE_V2") &&
                        meta[1] == id && hex(meta[2], 24) && hex(meta[3], 64) &&
                        (meta[4] == "schema3-1" || (legacyMigration && meta[4] == "schema2-1")) && hex(meta[5], 64) &&
                        (meta[6] == "none" || generationId(meta[6])) && hex(meta[7], 64) && meta.back().empty(),
                    "canonical metadata");
            state.user = canonical(effective);
            state.canonical = true;
            if (state.library) {
                state.upstream = d.get("upstream.conf", RULE_LIMIT);
                state.upstreamMetadata = d.get("upstream.metadata.json", 8192);
                require(sha256(state.upstream) == meta[8] && sha256(state.upstreamMetadata) == meta[9] &&
                            canonical(state.upstream) == state.upstream,
                        "upstream binding");
            }
            state.transaction = meta[2];
            state.provenance = d.get("provenance.txt", 16384);
            state.source = d.get("source.bin", PACK_LIMIT);
            require(sha256(state.source) == meta[7], "canonical source digest");
            require(sha256(state.user) == meta[3] && sha256(state.provenance) == meta[5], "canonical digest");
            auto previous = d.get("last_good.conf", RULE_LIMIT);
            require((previous.empty() ? "none" : generationOf(previous)) == meta[6], "canonical previous generation");
            return state;
        }
        require(legacyMigration, "explicit legacy store migration required", ErrorCode::CONFIG);
        auto metadata = d.get("pack_state.conf", 8192);
        auto rows = fields(metadata, '\n');
        require(rows.size() >= 5 && rows[0] == "ZUIOPT_RULE_STATE_V1" && rows.back().empty(), "state header");
        auto legacyFactory = root.get("migration_factory.conf", RULE_LIMIT, true);
        if (legacyFactory.empty())
            legacyFactory = factory;
        require(rows[1] == "factory " + sha256(legacyFactory), "factory migration required");
        auto tx = fields(rows[2], ' '), user = fields(rows[3], ' ');
        require(tx.size() == 2 && hex(tx[1], 24) && user.size() == 2 && hex(user[1], 64), "state identity");
        state.transaction = tx[1];
        state.user = d.get("user_rules.conf", RULE_LIMIT);
        require(sha256(state.user) == user[1], "stored user digest");
        parse(state.user);
        PrivateDir packs(d, "imported_packs");
        for (size_t i = 4; i + 1 < rows.size(); i++) {
            auto p = fields(rows[i], ' ');
            require(p.size() == 4 && p[0] == "pack" && packId(p[1]) && (p[2] == "0" || p[2] == "1") && hex(p[3], 64) &&
                        !state.packs.count(p[1]) && state.packs.size() < PACK_COUNT,
                    "stored pack state");
            auto data = packs.get(p[1] + ".zip", PACK_LIMIT);
            require(sha256(data) == p[3], "stored archive digest");
            auto pack = unpackPack(data, {}, true);
            require(pack.manifest.at("pack_id").text == p[1], "stored pack ID");
            state.packs.emplace(p[1], std::move(pack));
            if (p[2] == "1")
                state.enabled.insert(p[1]);
        }
        std::vector<Pack> selected;
        for (const auto &p : state.enabled)
            selected.push_back(state.packs.at(p));
        auto merged = rules(mergeRules(migrateSchema3Rules(legacyFactory), selected, migrateSchema3Rules(state.user)));
        merged.schema = parse(effective).schema;
        require(effective == "# ZUIOPT_GENERATION " + id + "\n" + legacyCanonical(merged),
                "stored effective derivation");
        return state;
    }
    std::string commit(RuleState state, const std::string &transaction, const std::string &expected,
                       const std::string *previousOverride = nullptr, bool activate = true) {
        require(hex(transaction, 24), "commit transaction");
        const auto active = root.get("effective.conf", RULE_LIMIT, true);
        require((active.empty() ? "none" : generationOf(active)) == expected && active == state.effective,
                "generation conflict");
        auto canonical = dumpRules(rules(state.user));
        std::string id = 'g' + randomId();
        auto effective = "# ZUIOPT_GENERATION " + id + "\n" + canonical;
        rules(effective);
        require(!generations.exists(id), "generation collision");
        PrivateDir d(generations, id, true);
        // Prepared/failed generations remain unmarked; only completed unreferenced history may be retired.
        std::string provenance = state.provenance;
        if (provenance.empty())
            provenance = "source=canonical\n";
        if (state.source.empty())
            state.source = state.user;
        if (state.upstream.empty()) {
            auto seed = root.get("migration_factory.conf", RULE_LIMIT, true);
            state.upstream = dumpRules(rules(seed.empty() ? factory : seed));
            state.upstreamMetadata =
                "{\"source\":\"FROZEN_FACTORY_SEED\",\"rulesHash\":\"" + sha256(state.upstream) + "\"}";
        }
        const auto previous = previousOverride ? *previousOverride : active;
        const auto priorId = previous.empty() ? "none" : generationOf(previous);
        const auto metadata = "ZUIOPT_CANONICAL_STATE_V3\n" + id + "\n" + transaction + "\n" + sha256(canonical) +
                              "\nschema3-1\n" + sha256(provenance) + "\n" + priorId + "\n" + sha256(state.source) +
                              "\n" + sha256(state.upstream) + "\n" + sha256(state.upstreamMetadata) + "\n";
        d.put("source.bin", state.source, true);
        d.put("last_good.conf", previous, true);
        d.put("provenance.txt", provenance, true);
        d.put("upstream.conf", state.upstream, true);
        d.put("upstream.metadata.json", state.upstreamMetadata, true);
        d.put("canonical_state.v3", metadata, true);
        d.put("effective.conf", effective, true);
        d.sync();
        generations.sync();
#ifdef ZUIOPT_TEST
        if (testBeforeCommit)
            throw std::runtime_error("injected before commit");
#endif
        if (!activate)
            return id;
        migrationBoundary(3);
        // Rename is the sole commit point. A following fsync error is indeterminate; query exact bytes.
        root.put("effective.conf", effective);
#ifdef ZUIOPT_TEST
        if (testAfterCommit)
            throw std::runtime_error("injected after commit");
#endif
        require(root.get("effective.conf", RULE_LIMIT) == effective, "committed readback");
        try {
            d.put("committed.v2", id + "\n");
            pruneCompleted();
        } catch (...) {
        }
        return id;
    }
    void removeRetired(const std::string &marker) {
        require(marker.rfind("retired-", 0) == 0 && generationId(marker.substr(8)), "retired generation name");
        auto id = marker.substr(8);
        require(generations.get(marker, 64) == id + "\n", "retirement marker identity");
        if (generations.exists(id)) {
            PrivateDir retired(generations, id);
            const std::set<std::string> allowed{
                "source.bin",    "last_good.conf",         "provenance.txt", "canonical_state.v2", "canonical_state.v3",
                "upstream.conf", "upstream.metadata.json", "effective.conf", "committed.v2"};
            auto entries = retired.names();
            for (const auto &entry : entries)
                require(allowed.count(entry), "unknown retired entry");
            for (const auto &entry : entries)
                retired.remove(entry);
            require(unlinkat(generations.fd, id.c_str(), AT_REMOVEDIR) == 0, "generation retirement");
            generations.sync();
        }
        generations.remove(marker);
    }
    void pruneCompleted() noexcept {
        try {
            // A pending cross-owner restore is never a GC boundary.
            if (root.exists("settings.pending"))
                return;
            auto active = root.get("effective.conf", RULE_LIMIT);
            auto id = generationOf(active);
            std::set<std::string> keep{id};
            PrivateDir currentDir(generations, id);
            auto previous = currentDir.get("last_good.conf", RULE_LIMIT, true);
            if (!previous.empty())
                keep.insert(generationOf(previous));
            auto loaded = fields(trim(root.get("loaded-generation.v2", 256, true)), ':');
            if (!loaded.empty() && generationId(loaded[0]))
                keep.insert(loaded[0]);
            std::vector<std::string> completed;
            for (const auto &name : generations.names(4096))
                if (name.rfind("retired-", 0) == 0 && generationId(name.substr(8)))
                    removeRetired(name);
            for (const auto &name : generations.names(4096)) {
                if (!generationId(name) || keep.count(name))
                    continue;
                PrivateDir candidate(generations, name);
                // Legacy and failed/prepared evidence is not guessed to be completed.
                if (candidate.get("committed.v2", 64, true) == name + "\n")
                    completed.push_back(name);
            }
            std::sort(completed.begin(), completed.end());
            const std::set<std::string> allowed{
                "source.bin",    "last_good.conf",         "provenance.txt", "canonical_state.v2", "canonical_state.v3",
                "upstream.conf", "upstream.metadata.json", "effective.conf", "committed.v2"};
            for (size_t i = 8; i < completed.size(); ++i) {
                PrivateDir candidate(generations, completed[i]);
                auto entries = candidate.names();
                for (const auto &name : entries)
                    require(allowed.count(name), "unknown generation retention entry");
                // load validates the canonical payload and embedded previous bytes before deleting.
                load(candidate.get("effective.conf", RULE_LIMIT));
                // A durable sibling FILE marker resumes partial deletion using existing file-rename/rmdir grants.
                auto retired = "retired-" + completed[i];
                generations.put(retired, completed[i] + "\n", true);
                removeRetired(retired);
            }
        } catch (...) {
        } // Retention cannot turn a durable successful commit into a failed transaction.
    }
    void migrationBoundary(int point) {
#ifdef ZUIOPT_TEST
        if (testMigrationFault == point)
            kill(getpid(), SIGKILL);
#else
        (void)point;
#endif
    }
    static void migrationCopy(const PrivateDir &target, const std::string &name, const std::string &data) {
        if (target.exists(name))
            require(target.get(name, PACK_LIMIT) == data, "immutable migration input identity", ErrorCode::CONFIG);
        else
            target.put(name, data, true);
    }
    void finishSchema3Migration() {
        auto pending = trim(root.get("schema3-migration.pending", 64, true));
        if (pending.empty())
            return;
        require(generationId(pending), "migration pending generation", ErrorCode::CONFIG);
        PrivateDir backups(root, "schema3-migration-backups"), backup(backups, pending);
        if (backup.exists("complete.v1")) {
            root.remove("schema3-migration.pending");
            return;
        }
        if (!backup.exists("rollback-effective.conf"))
            return;
        auto state = current();
        require(rules(state.user).schema == 3 && rules(state.upstream).schema == 3, "migration final format",
                ErrorCode::CONFIG);
        // Only invalidate the exact pre-migration upload, never a newly created Owner transaction.
        if (root.exists("upload.meta") && root.get("upload.meta", 512) == backup.get("old-upload.meta", 512) &&
            root.get("upload.bin", PACK_LIMIT) == backup.get("old-upload.bin", PACK_LIMIT))
            clearUpload();
        if (root.exists("library-preview.v1") &&
            root.get("library-preview.v1", PACK_LIMIT) == backup.get("old-library-preview.v1", PACK_LIMIT))
            root.remove("library-preview.v1");
        migrationBoundary(5);
        backup.put("complete.v1",
                   "ZUIOPT_SCHEMA3_MIGRATION_V1\nold_effective_sha256=" +
                       sha256(backup.get("old-effective.conf", RULE_LIMIT)) +
                       "\ncurrent=" + generationOf(state.effective) +
                       "\nrollback=" + generationOf(backup.get("rollback-effective.conf", RULE_LIMIT)) + "\n",
                   true);
        root.remove("schema3-migration.pending");
    }
    void migrateSchema3State() {
        require(!readOnly && !root.exists("settings.pending"), "migration settings recovery required",
                ErrorCode::CONFIG);
        auto active = root.get("effective.conf", RULE_LIMIT);
        auto old = load(active, true); // Full old content/hash verification precedes any migration write.
        PrivateDir backups(root, "schema3-migration-backups", true), backup(backups, generationOf(active), true),
            original(generations, generationOf(active));
        migrationCopy(backup, "old-effective.conf", active);
        migrationCopy(backup, "old-upstream.conf", old.upstream);
        migrationCopy(backup, "old-metadata.json", old.upstreamMetadata);
        migrationCopy(backup, "old-source.bin", old.source);
        migrationCopy(backup, "old-last-good.conf", original.get("last_good.conf", RULE_LIMIT, true));
        migrationCopy(backup, "old-factory.conf", root.get("migration_factory.conf", RULE_LIMIT, true));
        for (const auto *name : {"upload.meta", "upload.bin", "library-preview.v1"})
            migrationCopy(backup, std::string("old-") + name, root.get(name, PACK_LIMIT, true));
        for (const auto &name : original.names()) {
            if (name == "imported_packs") {
                PrivateDir packs(original, name), saved(backup, "imported_packs", true);
                for (const auto &file : packs.names())
                    migrationCopy(saved, file, packs.get(file, PACK_LIMIT));
            } else
                migrationCopy(backup, "generation-" + name, original.get(name, PACK_LIMIT));
        }
        backup.sync();
        root.sync();
        root.put("schema3-migration.pending", generationOf(active) + "\n");
        migrationBoundary(1);
        auto migrated = old;
        migrated.user = migrateSchema3Rules(active);
        auto seed = root.get("migration_factory.conf", RULE_LIMIT, true);
        if (seed.empty())
            seed = factory;
        migrated.upstream = migrateSchema3Rules(old.upstream.empty() ? seed : old.upstream);
        if (old.upstream.empty())
            migrated.upstreamMetadata =
                "{\"source\":\"FROZEN_FACTORY_SEED\",\"rulesHash\":\"" + sha256(migrated.upstream) + "\"}";
        else {
            auto metadata = ManifestJson(old.upstreamMetadata).parse();
            for (const auto *key : {"rulesHash", "newUpstreamHash"})
                if (metadata.count(key)) {
                    require(metadata[key].text == sha256(old.upstream), "migration upstream metadata identity",
                            ErrorCode::CONFIG);
                    metadata[key].text = sha256(migrated.upstream);
                }
            migrated.upstreamMetadata = jsonText(metadata);
        }
        migrated.provenance = "migration=SCHEMA2_TO_SCHEMA3\nold_effective_sha256=" + sha256(active) +
                              "\nold_upstream_sha256=" + sha256(old.upstream) + "\n";
        std::string previous;
        if (backup.exists("rollback-effective.conf")) {
            previous = backup.get("rollback-effective.conf", RULE_LIMIT);
            auto point = load(previous);
            require(point.user == migrated.user && point.upstream == migrated.upstream &&
                        point.upstreamMetadata == migrated.upstreamMetadata,
                    "migration rollback point identity", ErrorCode::CONFIG);
        } else {
            const std::string none;
            auto point = commit(migrated, randomId(), generationOf(active), &none, false);
            PrivateDir prepared(generations, point);
            previous = prepared.get("effective.conf", RULE_LIMIT);
            migrationCopy(backup, "rollback-effective.conf", previous);
            migrationCopy(backup, "rollback-upstream.conf", migrated.upstream);
            migrationCopy(backup, "rollback-metadata.json", migrated.upstreamMetadata);
        }
        migrationBoundary(2);
        commit(migrated, randomId(), generationOf(active), &previous);
        migrationBoundary(4);
        finishSchema3Migration();
    }
    void clearUpload() {
        // Preserve successful and failed input receipts; only the active transport slots are cleared.
        auto meta = root.get("upload.meta", 512, true);
        if (!meta.empty()) {
            auto f = fields(trim(meta), ':');
            require(!f.empty() && hex(f[0], 24), "upload receipt identity");
            PrivateDir receipts(root, "uploads", true);
            receipts.put(f[0] + ".meta", meta);
            receipts.put(f[0] + ".bin", root.get("upload.bin", PACK_LIMIT, true));
        }
        root.remove("upload.meta");
        root.remove("upload.bin");
        if (root.exists("uploads")) {
            PrivateDir receipts(root, "uploads");
            std::vector<std::string> completed;
            for (const auto &name : receipts.names(4096))
                if (name.size() == 29 && name.substr(24) == ".meta" && hex(name.substr(0, 24), 24))
                    completed.push_back(name.substr(0, 24));
            std::sort(completed.begin(), completed.end());
            for (size_t i = 16; i < completed.size(); ++i) {
                receipts.remove(completed[i] + ".bin");
                receipts.remove(completed[i] + ".meta");
            }
        }
    }
    std::vector<std::string> upload(const std::string &id) {
        require(hex(id, 24), "transaction ID");
        auto f = fields(trim(root.get("upload.meta", 512)), ':');
        require(f.size() == 9 && f[0] == id &&
                    (f[1] == "pack" || f[1] == "library" || f[1] == "user" || f[1] == "appopt") &&
                    rx(f[2], "[0-9]{1,6}") && number(f[2]) > 0 &&
                    number(f[2]) <= static_cast<int>((f[1] == "pack" || f[1] == "library") ? PACK_LIMIT : RULE_LIMIT) &&
                    hex(f[3], 64) && (f[4] == "-" || packId(f[4])) && rx(f[5], "-?[0-9]{1,7}"),
                "upload metadata");
        auto boot = trim(read("/proc/sys/kernel/random/boot_id"));
        require(generationId(f[6]) && f[7] == boot && rx(f[8], "[0-9]{1,16}"), "expired upload boot");
        auto begun = std::stoll(f[8]);
        require(begun <= now() && now() - begun <= 600000, "expired upload window");
        return f;
    }

  public:
#ifdef ZUIOPT_TEST
    inline static bool testBeforeCommit = false;
    inline static bool testAfterCommit = false;
    inline static int testMigrationFault = 0;
#endif
    RuleStore(const std::string &path, const std::string &factoryText, bool onlyRead = false)
        : root(path), generations(root, "generations", !onlyRead), factory(factoryText), readOnly(onlyRead) {
        rules(factory);
        factorySha = sha256(factory);
        lockFd =
            openat(root.fd, "manager.lock", (readOnly ? O_RDONLY : O_RDWR | O_CREAT) | O_CLOEXEC | O_NOFOLLOW, 0600);
        try {
            PrivateDir::file(lockFd);
            require(flock(lockFd, readOnly ? LOCK_SH | LOCK_NB : LOCK_EX) == 0,
                    readOnly ? "RULES_READ_BUSY" : "rule manager lock");
        } catch (...) {
            if (lockFd >= 0)
                close(lockFd);
            lockFd = -1;
            throw;
        }
    }
    ~RuleStore() {
        if (lockFd >= 0)
            close(lockFd);
    }
    RuleState current() {
        return load(root.get("effective.conf", RULE_LIMIT, true));
    }
    void initialize() {
        require(!readOnly, "read-only store");
        auto active = root.get("effective.conf", RULE_LIMIT, true);
        if (!active.empty()) {
            PrivateDir generation(generations, generationOf(active));
            auto metadata = fields(generation.get("canonical_state.v3", 2048, true), '\n');
            if (metadata.size() != 11 || metadata[4] != "schema3-1")
                migrateSchema3State();
            finishSchema3Migration();
        }
        auto s = current();
        if (s.canonical && s.library)
            return;
        if (s.canonical) {
            s.provenance = "migration=UPSTREAM_LIBRARY_SEED\nprevious_effective_sha256=" + sha256(s.user) + "\n";
            commit(s, randomId(), generationOf(s.effective));
            return;
        }
        // load() above verifies exact V1 merge once. Its immutable inputs remain untouched.
        s.provenance =
            "migration=V1_to_V2\nfactory_sha256=" + factorySha + "\nold_effective_sha256=" + sha256(s.effective) + "\n";
        if (s.effective.empty()) {
            s.user = dumpRules(rules(factory));
            s.provenance += "source=factory_seed\n";
        } else {
            s.provenance += "legacy_generation=" + generationOf(s.effective) + "\nuser_sha256=" + sha256(s.user) + "\n";
            for (const auto &[name, p] : s.packs)
                s.provenance += "pack=" + name + "|" + sha256(p.archive) + "\n";
            s.user = dumpRules(rules(s.effective));
        }
        // Snapshot factory bytes as well as its digest, even after a future ROM replacement.
        if (!root.exists("migration_factory.conf"))
            root.put("migration_factory.conf", factory, true);
        commit(s, randomId(), s.effective.empty() ? "none" : generationOf(s.effective));
    }
    std::string state() {
        return state(current());
    }
    std::string state(const RuleState &s) {
        require(!s.effective.empty(), "store not initialized");
        std::ostringstream out;
        const auto userHash = sha256(s.user); // One immutable, already verified content snapshot.
        out << "settings_pending=" << trim(root.get("settings.pending", 64, true))
            << "\nstore_schema=ZUIOPT_CANONICAL_STATE_V3\ncanonical_sha256=" << userHash
            << "\nloaded_generation=" << trim(root.get("loaded-generation.v2", 256, true))
            << "\ngeneration=" << generationOf(s.effective) << "\ntransaction=" << s.transaction
            << "\nfactory_sha256=" << factorySha << "\nuser_size=" << s.user.size() << "\nuser_sha256=" << userHash
            << "\neffective_sha256=" << sha256(s.effective) << '\n';
        out << "upstream_sha256=" << sha256(s.upstream) << "\nupstream_size=" << s.upstream.size()
            << "\nupstream_metadata_size=" << s.upstreamMetadata.size() << "\n";
        PrivateDir active(generations, generationOf(s.effective));
        auto previous = active.get("last_good.conf", RULE_LIMIT, true);
        out << "previous_generation=" << (previous.empty() ? "none" : generationOf(previous)) << '\n';
        for (const auto &[id, p] : s.packs)
            out << "pack=" << id << '|' << p.manifest.at("pack_version").text << '|'
                << p.manifest.at("pack_priority").text << '|' << s.enabled.count(id) << '|'
                << p.manifest.at("source_type").text << '\n';
        require(out.str().size() <= 4096, "state response bound");
        return out.str();
    }
    /** Existing canonical parser/lock; no staging, persistence or runtime placement. */
    std::string readReply(const std::string &argument) {
        require(readOnly, "read-only store required");
        bool snapshot = argument.rfind("snapshot|", 0) == 0;
        bool runtime = argument.rfind("runtime|", 0) == 0;
        require(argument == "state" || (snapshot && generationId(argument.substr(9))) ||
                    (runtime && generationId(argument.substr(8))),
                "rules read argument");
        auto s = current();
        require(s.canonical && s.library, "canonical library required");
        if (snapshot)
            require(generationOf(s.effective) == argument.substr(9), "rules read generation changed");
        if (runtime)
            require(generationOf(s.effective) == argument.substr(8), "runtime read generation changed");
        auto status = state(s) + failureState() + "upstream_metadata_sha256=" + sha256(s.upstreamMetadata) +
                      "\nrules_read_transport=DAEMON_SNAPSHOT_V1\n";
        require(status.size() <= 4608, "rules read state bound");
        if (runtime) {
            auto body = root.get("runtime-status.v1", RUNTIME_STATUS_LIMIT);
            std::string owner;
            for (const auto &line : fields(status, '\n'))
                if (line.rfind("loaded_generation=", 0) == 0)
                    owner = line.substr(18);
            auto identityFields = fields(owner, ':');
            require(identityFields.size() == 5 && identityFields[0] == argument.substr(8) &&
                        identityFields[2] == std::to_string(getpid()) &&
                        identityFields[3] == std::to_string(identity(getpid()).start),
                    "runtime current daemon identity");
            require(runtimeOwnerMatches(body, trim(read("/proc/sys/kernel/random/boot_id")), owner),
                    "runtime owner frame");
            auto reply = "ZUIOPT_RUNTIME_SNAPSHOT_V1\nstate=" + base64(status) + "\nruntime=" + base64(body) + "\n";
            require(reply.size() <= 51000, "runtime read frame bound");
            return reply;
        }
        if (!snapshot)
            return status;
        auto reply = "ZUIOPT_READ_SNAPSHOT_V1\nstate=" + base64(status) + "\nuser=" + base64(s.user) +
                     "\nupstream=" + base64(s.upstream) + "\nmetadata=" + base64(s.upstreamMetadata) + "\n";
        require(reply.size() <= 200000, "rules read snapshot bound");
        return reply;
    }
    bool loaded() {
        auto effective = current().effective;
        auto receipt = fields(trim(root.get("loaded-generation.v2", 256, true)), ':');
        if (receipt.size() != 5 || receipt[0] != generationOf(effective) ||
            receipt[1] != trim(read("/proc/sys/kernel/random/boot_id")) || !rx(receipt[2], "[0-9]{1,10}") ||
            !rx(receipt[3], "[0-9]{1,20}") || receipt[4] != sha256(effective))
            return false;
        return identity(number(receipt[2])).start != 0 &&
               std::to_string(identity(number(receipt[2])).start) == receipt[3];
    }
    std::string userChunk(const std::string &generation, const std::string &offsetText) {
        require(rx(offsetText, "[0-9]{1,6}"), "read offset");
        size_t offset = number(offsetText);
        auto s = current();
        require(generationOf(s.effective) == generation && offset <= s.user.size(), "state changed/read offset");
        return generation + ":" + offsetText + ":" + base64(s.user.substr(offset, 8192));
    }
    std::string settings(const std::string &action, const std::string &tx, const std::string &value) {
        require(!readOnly, "read-only store");
        require(hex(tx, 24), "settings transaction");
        auto s = current();
        require(s.canonical, "canonical required");
        auto lease = trim(root.get("settings.pending", 64, true));
        const auto before = "settings-" + tx + "-before.conf", target = "settings-" + tx + "-target.conf";
        if (action == "settings_prepare") {
            auto colon = value.find(':');
            require(colon != std::string::npos, "settings prepare metadata");
            auto expected = value.substr(0, colon), data = unbase64(value.substr(colon + 1), RULE_LIMIT);
            require(data.size() <= RULE_LIMIT && dumpRules(rules(data)) == data, "settings canonical bytes");
            require(lease.empty() || lease == tx, "settings busy");
            if (lease == tx) {
                require(root.get(target, RULE_LIMIT) == data, "settings prepare replay");
            } else {
                require(generationOf(s.effective) == expected, "settings generation CAS");
                // Retained stage inputs precede the durable freeze; no visible rule changes here.
                if (root.exists(before))
                    require(root.get(before, RULE_LIMIT) == s.user && root.get(target, RULE_LIMIT) == data,
                            "settings immutable stage");
                else {
                    root.put(before, s.user, true);
                    root.put(target, data, true);
                }
                root.put("settings.pending", tx + "\n");
            }
            return "prepared=" + sha256(data);
        }
        require(lease == tx || (lease.empty() && action == "settings_finish"), "settings lease");
        if (action == "settings_finish") {
            root.remove("settings.pending");
            // Release is idempotent; the current pair remains available for diagnostic replay.
            std::vector<std::string> stages;
            for (const auto &name : root.names(4096))
                if (rx(name, "settings-[0-9a-f]{24}-(before|target)\\.conf") && name != before && name != target)
                    stages.push_back(name);
            std::sort(stages.begin(), stages.end());
            for (size_t i = 16; i < stages.size(); ++i)
                root.remove(stages[i]);
            pruneCompleted();
            return "settings=finished";
        }
        require(action == "settings_apply" || action == "settings_revert", "settings action");
        auto old = root.get(before, RULE_LIMIT), next = root.get(target, RULE_LIMIT);
        require(s.user == old || s.user == next, "settings unknown active rules");
        auto wanted = action == "settings_apply" ? next : old;
        require(value == sha256(wanted), "settings wanted digest");
        if (s.user != wanted) {
            auto expected = generationOf(s.effective);
            s.user = wanted;
            s.source = wanted;
            s.provenance = "source=settings_restore\ntransaction=" + tx + "\n";
            commit(s, randomId(), expected);
        }
        return "canonical_sha256=" + sha256(wanted);
    }
    std::string apply(const std::string &action, const std::string &id, const std::string &value) {
        require(!readOnly || action == "upstream_read", "read-only store");
        auto s = current();
        require(s.canonical, "canonical migration required");
        require(!root.exists("settings.pending"), "settings restore recovery required");
        if (action == "upstream_read") {
            auto input = fields(value, ':');
            require(input.size() == 2 && (input[0] == "rules" || input[0] == "metadata") && rx(input[1], "[0-9]{1,6}"),
                    "upstream read arguments");
            require(id == generationOf(s.effective) && s.library, "upstream changed");
            auto text = input[0] == "rules" ? s.upstream : s.upstreamMetadata;
            size_t offset = number(input[1]);
            require(offset <= text.size(), "upstream read offset");
            return id + ":" + input[1] + ":" + base64(text.substr(offset, 8192));
        }
        if (action == "begin") {
            require(hex(id, 24), "upload ID");
            auto f = fields(value, ':');
            require(f.size() == 6 && generationId(f[5]) && f[5] == generationOf(s.effective) &&
                        (f[0] == "pack" || f[0] == "library" || f[0] == "user" || f[0] == "appopt") &&
                        rx(f[1], "[0-9]{1,6}") && hex(f[2], 64) && (f[3] == "-" || packId(f[3])) &&
                        rx(f[4], "-?[0-9]{1,7}"),
                    "begin metadata");
            int size = number(f[1]), priority = number(f[4]);
            require(size > 0 &&
                        size <= static_cast<int>((f[0] == "pack" || f[0] == "library") ? PACK_LIMIT : RULE_LIMIT) &&
                        priority >= -1000000 && priority <= 1000000 && (f[0] != "appopt" || packId(f[3])),
                    "begin bounds");
            if (root.exists("upload.meta")) {
                auto old = fields(trim(root.get("upload.meta", 512)), ':');
                bool active = false;
                try {
                    if (!old.empty()) {
                        upload(old[0]);
                        active = true;
                    }
                } catch (...) {
                }
                if (active) {
                    require(old[0] == id && trim(root.get("upload.meta", 512)).rfind(id + ":" + value + ":", 0) == 0,
                            "upload busy");
                    return "upload=resumed";
                }
                clearUpload();
            }
            root.put("upload.bin", "");
            root.put("upload.meta", id + ":" + value + ":" + trim(read("/proc/sys/kernel/random/boot_id")) + ":" +
                                        std::to_string(now()) + "\n");
            return "upload=begun";
        }
        if (action == "abort") {
            if (root.exists("upload.meta")) {
                upload(id);
                clearUpload();
            }
            return "upload=aborted";
        }
        if (action == "chunk") {
            auto key = fields(id, ':');
            require(key.size() == 2 && rx(key[1], "[0-9]{1,6}"), "chunk key");
            auto f = upload(key[0]);
            size_t offset = number(key[1]);
            auto bytes = unbase64(value), data = root.get("upload.bin", PACK_LIMIT);
            require(offset <= data.size() && offset + bytes.size() <= static_cast<size_t>(number(f[2])),
                    "chunk offset/declared size");
            if (offset < data.size()) {
                require(offset + bytes.size() <= data.size() && data.substr(offset, bytes.size()) == bytes,
                        "conflicting chunk replay");
                return "chunk=replayed";
            }
            root.put("upload.bin", data + bytes);
            return "received=" + std::to_string(data.size() + bytes.size());
        }
        if (action == "validate") {
            require(value.empty(), "validation arguments");
            auto f = upload(id);
            require(f[1] == "user", "validation requires canonical input");
            auto data = root.get("upload.bin", RULE_LIMIT);
            require(data.size() == static_cast<size_t>(number(f[2])) && sha256(data) == f[3],
                    "validation length/SHA256");
            // No commit, generation write, upload clearing or owner reload on this path.
            try {
                auto normalized = dumpRules(rules(data));
                return "validation=PASS\nnormalized_sha256=" + sha256(normalized);
            } catch (const std::exception &e) {
                std::string error = e.what();
                for (char &c : error)
                    if (c < ' ' || c > '~')
                        c = ' ';
                return "validation=FAIL\nerror=" + error.substr(0, 160);
            }
        }
        if (action == "preview") {
            auto f = upload(id);
            require(f[6] == generationOf(s.effective) && rx(value, "[0-9]{1,3}"), "preview generation/offset");
            auto data = root.get("upload.bin", PACK_LIMIT);
            require(data.size() == static_cast<size_t>(number(f[2])) && sha256(data) == f[3], "preview input digest");
            LibraryMerge merged;
            if (f[1] == "library") {
                auto p = libraryPack(data, sha256(s.upstream));
                auto manual = rules(p.manual);
                merged =
                    mergeLibrary(rules(s.upstream), rules(s.user), rules(p.upstream), p.decisions, &manual, p.partial);
            } else {
                require(f[1] == "appopt", "preview requires library or AppOpt input");
                auto p = importAppOpt(data, f[4], number(f[5]));
                merged = mergeLibrary(rules(s.upstream), rules(s.user), p.config, {}, nullptr, true);
            }
            auto page = libraryPreview(merged, number(value));
            root.put("library-preview.v1",
                     id + ":" + f[3] + ":" + f[6] + ":" + sha256(s.upstream) + ":" + sha256(merged.canonical));
            return page;
        }
        if (action == "commit") {
            auto f = upload(id);
            std::string result;
            try {
                require(f[6] == generationOf(s.effective), "generation conflict");
                auto data = root.get("upload.bin", PACK_LIMIT);
                require(data.size() == static_cast<size_t>(number(f[2])) && sha256(data) == f[3],
                        "upload length/SHA256");
                if (f[1] == "user")
                    s.user = dumpRules(rules(data));
                else if (f[1] == "pack")
                    s.user = dumpRules(unpackPack(data, s.user).config);
                else {
                    LibraryMerge merged;
                    std::string upstream = s.upstream, metadata = s.upstreamMetadata;
                    if (f[1] == "library") {
                        auto p = libraryPack(data, sha256(s.upstream));
                        auto manual = rules(p.manual);
                        merged = mergeLibrary(rules(s.upstream), rules(s.user), rules(p.upstream), p.decisions, &manual,
                                              p.partial);
                        if (!p.partial) {
                            upstream = p.upstream;
                            metadata = p.metadata;
                        }
                    } else {
                        auto p = importAppOpt(data, f[4], number(f[5]));
                        merged = mergeLibrary(rules(s.upstream), rules(s.user), p.config, {}, nullptr, true);
                    }
                    require(root.get("library-preview.v1", 512) == id + ":" + f[3] + ":" + f[6] + ":" +
                                                                       sha256(s.upstream) + ":" +
                                                                       sha256(merged.canonical),
                            "exact library preview required");
                    s.user = merged.canonical;
                    s.upstream = upstream;
                    s.upstreamMetadata = metadata;
                }
                s.source = data;
                s.provenance =
                    "source=" + f[1] + "\nsource_sha256=" + sha256(data) + "\nbase_generation=" + f[6] + "\n";
                result = commit(s, id, f[6]);
            } catch (...) {
                try {
                    clearUpload();
                } catch (...) {
                }
                throw;
            }
            try {
                clearUpload();
            } catch (...) {
            }
            return "generation=" + result;
        }
        if (action == "enable" || action == "disable")
            throw std::runtime_error("canonical store has no live pack layers");
        if (action == "restore_app") {
            auto f = fields(value, ':');
            require(id == generationOf(s.effective) && f.size() == 2 && packageLabel(f[0]) &&
                        f[1] == sha256(s.upstream),
                    "restore upstream CAS");
            auto baseline = rules(s.upstream);
            require(appBehavior(baseline, f[0]), "App absent from upstream");
            s.user = mergeLibrary(baseline, rules(s.user), baseline, {{f[0], "USE_UPSTREAM"}}).canonical;
            s.source = s.user;
            s.provenance = "source=restore_app_upstream\npackage=" + f[0] + "\n";
            return "generation=" + commit(s, randomId(), id);
        }
        if (action == "rollback") {
            require(generationId(id) && id == generationOf(s.effective), "generation conflict");
            PrivateDir d(generations, id);
            auto old = d.get("last_good.conf", RULE_LIMIT);
            require(!old.empty(), "no last good generation");
            auto restored = load(old);
            restored.user = dumpRules(rules(old));
            restored.effective = s.effective;
            restored.provenance = "source=rollback\nselected=" + generationOf(old) + "\n";
            return "generation=" + commit(restored, randomId(), id);
        }
        throw std::runtime_error("unknown rule manager action");
    }
    bool failed() {
        return root.exists("failure.v1");
    }
    std::string bootState() {
        return failed() ? "FAILSAFE" : "READY_TO_START";
    }
    std::string failureState() {
        std::string result = std::string("thread_manager=ZUIOPT\nfailure=") + (failed() ? "1" : "0") + "\n";
        if (!failed())
            return result + "failure_reason=NONE\nfailure_evidence_unix_seconds=0\n";
        auto lines = fields(root.get("failure.v1", 128), '\n');
        std::string reason = lines.size() > 2 ? lines[2] : "";
        if (reason.empty())
            reason = "CRASH_BUDGET_OR_OWNER_FAILURE";
        for (char &c : reason)
            if (c < ' ' || c > '~')
                c = ' ';
        struct stat info {};
        require(fstatat(root.fd, "failure.v1", &info, AT_SYMLINK_NOFOLLOW) == 0, "failure evidence stat");
        return result + "failure_reason=" + reason.substr(0, 96) +
               "\nfailure_evidence_unix_seconds=" + std::to_string(info.st_mtime) + "\n";
    }
    void resetFailure() {
        require(!readOnly, "read-only store");
        CrashLock lock(root);
        require(failed(), "no persistent failure");
        // Validate both before deleting either. Clear failure last; partial I/O
        // failure therefore remains safe. Never signal/restart the running boot.
        root.get("failure.v1", 128);
        root.get("crashes.v1", 256, true);
        root.remove("crashes.v1");
        root.remove("failure.v1");
    }
    void failure() {
        require(!readOnly, "read-only store");
        crashFailure(root);
    }
    bool crash() {
        require(!readOnly, "read-only store");
        return accountCrash(root);
    }
};
